// {{LABEL}} driver: fully automatic runs with error fallbacks. One tick every 5 minutes:
// machine running -> supervise (keeps an active run going; restarts the driver and the Kylon gateway after crashes or reboots)
// + n8n attestation + hosting watchdog. Machine stopped -> start it only while a run it saw running has not finished.
const sd = $getWorkflowStaticData('global');
const r = $input.first().json; let status = 'unknown';
try { const v = JSON.parse(r.body); const res = v.result || {}; const sc = res.structuredContent || JSON.parse(((res.content||[]).find(x=>x.type==='text')||{}).text||'{}'); status = sc.status || 'unknown'; } catch(e) { status = 'parse_error'; }
const call = (name, args) => ({jsonrpc:'2.0', id:'call', method:'tools/call', params:{name, arguments:args}});
if (status === 'stopped') {
  if (!sd.activeRun || sd.activeRun === sd.finishedRun) return [];   // idle or finished: stay off
  return [{json:{action:'start', status, run: sd.activeRun, rpc: call('cloud_computer_start', {name:'{{MACHINE_1}}'})}}];
}
if (status !== 'running') return [];   // starting, stopping, unknown: act on the next tick
const R = 'python3 /opt/{{SLUG}}/round.py';
const cmd = 'cd / && ' + R + ' supervise; ' + R + ' n8n-attest --execution ' + $execution.id + ' --workflow ' + $workflow.id + '; ' + R + ' watch';
return [{json:{action:'exec', status, rpc: call('cloud_computer_exec', {name:'{{MACHINE_1}}', command:cmd, timeout:150})}}];

// After supervise: remember the active run; when it finishes, stop all four machines once.
const sd = $getWorkflowStaticData('global');
const d = $('Decide').first().json; if (d.action !== 'exec') return [];
const body = $input.first().json.body; let text = String(body || '');
try { const v = JSON.parse(body); const res = v.result || {}; const sc = res.structuredContent; text = sc ? (typeof sc.stdout === 'string' ? sc.stdout : JSON.stringify(sc)) : (res.content||[]).map(x=>x.text).join('\n'); } catch(e) {}
try { const inner = JSON.parse(text); if (inner && typeof inner.stdout === 'string') text = inner.stdout; } catch(e) {}   // Celesto wraps stdout in a JSON text
let sup = null;
for (const line of text.split('\n')) { const t = line.trim(); if (t.startsWith('{"run"')) { try { sup = JSON.parse(t); break; } catch(e) {} } }
if (!sup) return [];
if (sup.run === 'running') { sd.activeRun = sup.id; return []; }
if (sup.run !== 'finished' || sd.finishedRun === sup.id) return [];
sd.finishedRun = sup.id; sd.activeRun = sup.id;
const stop = (name) => ({jsonrpc:'2.0', id:'call', method:'tools/call', params:{name:'cloud_computer_stop', arguments:{name}}});
return ['{{MACHINE_1}}','{{MACHINE_2}}','{{MACHINE_3}}','{{MACHINE_4}}'].map(n => ({json:{machine:n, rpc: stop(n)}}));
